#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-skip-unchanged-files-with-etags. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'alpha' > site/a.txt
printf '%s\n' 'beta' > site/b.txt
cat > sync.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# A sync job: fetches each file only when the server's entity tag differs from the one saved with it.
# Usage: sh sync.sh <base URL> <file>...
base=$1; shift
mkdir -p local
for f in "$@"; do
  curl -s -f --etag-compare "local/$f.etag" --etag-save "local/$f.etag" -o "local/$f" -w "%{http_code} $f\n" "$base$f"
done
EOF
touch -t 202401021504.05 site/a.txt site/b.txt
surl --directory site http://127.0.0.1:8080/ &
sleep 1
sh sync.sh http://127.0.0.1:8080/ a.txt b.txt
kill $(jobs -p)
